208	    /**
209	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
210	     * owner using the same telephone number.
211	     *
212	     * @param owner the candidate owner to check
213	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
214	     */
215	    private boolean isDuplicateOwner(Owner owner) {
216	        return this.clinicService.findAllOwners().stream()
217	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
218	    }
219	
220	    /**
221	     * Determines whether the given owner's email address is already used by another owner. An owner
222	     * without an email address never conflicts.
223	     *
224	     * @param owner the candidate owner to check
225	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
226	     */
227	    private boolean isDuplicateEmail(Owner owner) {
228	        String email = owner.getEmail();
229	        if (email == null || email.isBlank()) {
230	            return false;
231	        }
232	        return this.clinicService.findAllOwners().stream()
233	            .anyMatch(existing -> Objects.equals(existing.getEmail(), email));
234	    }
235	}
